  simple_modal_overlay_show(
    t("Important Notice"),
    array(
      '#type'   => 'fieldset',
      '#title'  => '',
      '#collapsible' => FALSE,
      '#collapsed' => FALSE,

      'content' => array(
        '#type' => 'markup',
        '#markup' => t('You are the accused in a new Dispute.') . ' ' . t('To take actions for dismissing the case or to defend your position, please first read the rules governing Disputes.') . ' ' . t('The rules and link to the Dispute can be found on the Disputes page.') . '<br/><br/><br/><br/>' . 
